{
  "status": "SUPPORTED",
  "task_summary": "Identify components, perform fastening, and place tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The specific assembly or fixture requiring a fastener to be secured.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly", "fixture", "workpiece"],
        "required_properties": ["needs securing"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The hardware part (screw, bolt, etc.) that fits and secures the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "fastener"],
        "required_properties": ["fits fastening_target", "secures fastening_target"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to drive or secure the component.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "driver", "tool"],
        "required_properties": ["drives compatible_component", "applies force to fastening_target"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The flat area where tools are placed after use.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["flat", "supports weight"]
      }
    ],
    "functional_relations": [
      {
        "id": "secures_relation",
        "relation": "compatible_component secures fastening_target",
        "participant_roles": [
          "compatible_component",
          "fastening_target"
        ]
      ,
      "required": true
      },
      {
        "id": "installation_relation",
        "relation": "fastening_tool installs compatible_component into fastening_target",
        "participant_roles": [
          "fastening_tool",
          "compatible_component",
          "fastening_target"
        ]
      ,
      "required": true
      },
      {
        "id": "placement_relation",
        "relation": "fastening_tool rests on workbench_surface",
        "participant_roles": [
          "fastening_tool",
          "workbench_surface"
        ]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_component",
        "operation": "Locate and select the compatible_component",
        "participant_roles": [
          "compatible_component",
          "fastening_target"
        ],
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "Secure the compatible_component using the fastening_tool",
        "participant_roles": [
          "fastening_tool",
          "compatible_component",
          "fastening_target"
        ],
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "Place the fastening_tool onto the workbench_surface",
        "participant_roles": [
          "fastening_tool",
          "workbench_surface"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "black tray-like object",
          "visual_description": "Rectangular dark object with yellow and blue elements sitting on the table surface."
        }
      ],
      "compatible_component": [
        {
          "label": "yellow/blue blocks",
          "visual_description": "Small geometric shapes on the tray; possibly parts of the target or loose components."
        }
      ],
      "fastening_tool": [
        {
          "label": "gold blocky object",
          "visual_description": "Yellow/gold blocky item held in the robot arm in the third view."
        }
      ],
      "workbench_surface": [
        {
          "label": "wooden table top",
          "visual_description": "Light brown wooden surface of the table."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue cabinet",
        "visual_description": "Tall blue cabinet standing against the back wall.",
        "reason": "Likely contains tools or spare fasteners hidden from view."
      },
      {
        "id": "table_drawers",
        "label": "table drawers",
        "visual_description": "Two blue drawers underneath the wooden table.",
        "reason": "Standard storage locations for small hardware and hand tools."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "table_drawers"
    ]
  },
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
